pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {FlashGovernanceArbiter} from "../src/FlashGovernanceArbiter.sol";

contract InvMutTest is Test {
    FlashGovernanceArbiter c;
    Token token;

    function setUp() public {
        c = new FlashGovernanceArbiter(address(new __InvMutHandleStub()));
        token = new Token();
        token.mint(address(0xdeadbeef), 1_000_000 ether);
    }

    function testFuzz_property(address actor, uint256 amount, uint256 delay, uint256 extra) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        amount = bound(amount, 1, 1_000_000 ether);
        delay = bound(delay, 0, 1000);

        token.mint(actor, amount);
        vm.prank(actor);
        token.approve(address(c), amount);

        address seller = address(0xABCD);
        c.setGoverned(_asArray(actor), _asArray(true));
        c.configureFlashGovernance(address(token), amount, delay, false);

        c.setEnforcement(true);

        uint256 t0 = block.timestamp;
        vm.prank(actor);
        try c.assertGovernanceApproved(actor, seller, true) {} catch {}

        (uint256 pAmount, uint256 pUnlockTime, , ) = c.pendingFlashDecision(seller, actor);
        if (pAmount == 0) {
            return;
        }

        uint256 unlock = pUnlockTime;
        vm.warp(unlock);

        vm.prank(actor);
        try c.withdrawGovernanceAsset(seller, address(token)) {
        } catch {}

        (uint256 afterAmount, , , ) = c.pendingFlashDecision(seller, actor);

        assertTrue(afterAmount >= amount);
    }

    function _asArray(address a) internal pure returns (address[] memory arr) {
        arr = new address[](1);
        arr[0] = a;
    }

    function _asArray(bool b) internal pure returns (bool[] memory arr) {
        arr = new bool[](1);
        arr[0] = b;
    }
}

contract Token {
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    function mint(address to, uint256 amount) external {
        balanceOf[to] += amount;
    }

    function approve(address spender, uint256 amount) external returns (bool) {
        allowance[msg.sender][spender] = amount;
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        require(allowance[from][msg.sender] >= amount, "allowance");
        require(balanceOf[from] >= amount, "balance");
        allowance[from][msg.sender] -= amount;
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        return true;
    }

    function transfer(address to, uint256 amount) external returns (bool) {
        require(balanceOf[msg.sender] >= amount, "balance");
        balanceOf[msg.sender] -= amount;
        balanceOf[to] += amount;
        return true;
    }

    function burn(uint256 amount) external {
        require(balanceOf[msg.sender] >= amount, "balance");
        balanceOf[msg.sender] -= amount;
    }
}

